R = "bev_fusion_lane_center/results/E2E_Final_Report_2026-11-18/parts/"
def sub(f, pairs):
    s = open(R + f, encoding="utf-8").read()
    for a, b in pairs:
        assert s.count(a) == 1, (f, a[:50], s.count(a))
        s = s.replace(a, b)
    open(R + f, "w", encoding="utf-8", newline="\n").write(s)
